1	/**
2	 * require-spec-link — every `it()`/`test()` must be linked to a spec or ADR.
3	 *
4	 * The spec-traceability convention authors the link INSIDE the spec.md/adr `.md`
5	 * as an inline trailing parenthetical — `Statement. ([validated by](test.ts#L42))`.
6	 * This rule inverts that view: it goes over each test declaration and fails the
7	 * ones that no spec or ADR statement references, so tests cannot silently drift
8	 * out of spec coverage.
9	 *
10	 * A test is linked when the spec/adr corpus carries a `([validated by](this#Lnn))`
11	 * link whose line falls inside the test's line span, or a whole-file link (no
12	 * `#L`) to the file. The corpus is read once per process (memoized per specsRoot)
13	 * via the shared parser — see `lib/spec-link-index.mjs`. Type info is off for
14	 * test files, so this works from the ESTree AST + filename + filesystem only.
15	 *
16	 * Detect-only: writing the link needs a human to pick which statement the test
17	 * validates, not a codemod.
18	 */
19	import path from "node:path";
20	import { isTestFile } from "./lib/spec-parsers.mjs";
21	import { buildLinkIndex, corpusExists, readSpecFiles, toPosix, } from "./lib/spec-link-index.mjs";
22	/**
23	 * specsRoot+roots → index, so the corpus is walked once per process.
24	 *
25	 * Note: the cache is keyed on specsRoot only, with no mtime/content hash — a
26	 * single-pass `eslint`/CI run always reads fresh, but a long-lived ESLint
27	 * server (VS Code extension, --watch) will not see a spec link added after the
28	 * first lint until the server restarts.
29	 */
30	const indexCache = new Map();
31	/** specsRoots we've already warned about having no spec/adr corpus, so a
32	 * misconfigured run warns once instead of once per linted test file.
33	 *
34	 * Scope is the whole Node process, matching `indexCache` above. In a one-shot
35	 * `eslint`/CI run that is exactly one warning. In a long-lived ESLint server
36	 * (VS Code, --watch) the module is not re-required between cycles, so once a
37	 * specsRoot has warned it stays quiet even after the CWD is fixed — the same
38	 * process-lifetime memoization caveat the corpus cache carries. Restart the
39	 * server (or the editor) to re-arm the warning. */
40	const warnedMissingCorpus = new Set();
41	function getIndex(specsRoot, roots) {
42	    // `\0` separates every element so no root value can collide with the joiner.
43	    const key = [specsRoot, ...roots].join("\0");
44	    let index = indexCache.get(key);
45	    if (!index) {
46	        index = buildLinkIndex(readSpecFiles(specsRoot, roots));
47	        indexCache.set(key, index);
48	    }
49	    return index;
50	}
51	/** The base identifier of a (possibly chained) callee — `it` in `it.each([])(…)`. */
52	function rootCallName(callee) {
53	    let node = callee;
54	    while (node) {
55	        if (node.type === "Identifier") {
56	            return node.name;
57	        }
58	        if (node.type === "MemberExpression") {
59	            node = node.object;
60	            continue;
61	        }
62	        if (node.type === "CallExpression") {
63	            node = node.callee;
64	            continue;
65	        }
66	        // `it.each`table`(name, fn)` — the outer callee is a tagged template whose
67	        // `.tag` is the `it.each` member chain; drill into it or the test escapes.
68	        if (node.type === "TaggedTemplateExpression") {
69	            node = node.tag;
70	            continue;
71	        }
72	        return null;
73	    }
74	    return null;
75	}
76	/** A named test declaration: `it`/`test` (any modifier chain) with a string name. */
77	function isNamedTestCall(node) {
78	    const root = rootCallName(node.callee);
79	    if (root !== "it" && root !== "test") {
80	        return false;
81	    }
82	    const first = node.arguments[0];
83	    if (!first) {
84	        return false;
85	    }
86	    if (first.type === "Literal") {
87	        return typeof first.value === "string";
88	    }
89	    return first.type === "TemplateLiteral";
90	}
91	function isLinked(entry, startLine, endLine) {
92	    if (!entry) {
93	        return false;
94	    }
95	    if (entry.wholeFile) {
96	        return true;
97	    }
98	    for (const line of entry.lines) {
99	        if (line >= startLine && line <= endLine) {
100	            return true;
101	        }
102	    }
103	    return false;
104	}
105	// With no corpus under specsRoot, every test would flag as unlinked — a
106	// false-positive storm that means the run started outside the repo root
107	// (e.g. `eslint apps/floor/` in a subdir). Warn once and skip rather than
108	// report thousands of misleading errors.
109	function warnMissingCorpusOnce(specsRoot, roots) {
110	    if (warnedMissingCorpus.has(specsRoot)) {
111	        return;
112	    }
113	    warnedMissingCorpus.add(specsRoot);
114	    console.warn(`require-spec-link: no ${roots.join("/")} directory under ${specsRoot} — ` +
115	        "run eslint from the repo root (or pass options.specsRoot). Skipping the spec-link check.");
116	}
117	function testName(sourceCode, first) {
118	    return first.type === "Literal"
119	        ? String(first.value)
120	        : sourceCode.getText(first);
121	}
122	function reportUnlinked(context, node, corpus) {
123	    if (!isNamedTestCall(node)) {
124	        return;
125	    }
126	    const startLine = node.loc.start.line;
127	    if (isLinked(corpus.entry, startLine, node.loc.end.line)) {
128	        return;
129	    }
130	    context.report({
131	        node: node.callee,
132	        messageId: "unlinkedTest",
133	        data: {
134	            name: testName(context.sourceCode, node.arguments[0]),
135	            file: corpus.relPath,
136	            line: String(startLine),
137	            roots: corpus.roots.map((root) => `${root}/**/*.md`).join(" or "),
